function csvSplit(line){return line.split(',').map(x=>x.trim());}
function parseHistoryCsv(buffer){const text=buffer.toString('utf8').replace(/^\uFEFF/,''),meta={},rows=[];let header=null;for(const rawLine of text.split(/\r?\n/)){const line=rawLine.trim();if(!line)continue;if(line.startsWith('#')){const parts=csvSplit(line.slice(1));if(parts.length>=2)meta[parts[0]]=parts.slice(1).join(',');continue;}if(!header){header=csvSplit(line);continue;}const parts=csvSplit(line);if(parts.length<header.length)continue;const obj=Object.fromEntries(header.map((h,i)=>[h,parts[i]])),utcEpoch=asNumber(obj.time_utc_epoch),serverDate=parseDateFlexible(obj.time_server),timeMs=utcEpoch!==null?utcEpoch*1000:serverDate?.getTime();if(!Number.isFinite(timeMs))continue;const row={tf:String(obj.tf||'').toUpperCase(),timeMs,timeIso:new Date(timeMs).toISOString(),timeServer:obj.time_server||'',open:asNumber(obj.open),high:asNumber(obj.high),low:asNumber(obj.low),close:asNumber(obj.close),tickVolume:asNumber(obj.tick_volume),spread:asNumber(obj.spread),realVolume:asNumber(obj.real_volume)};if(!TIMEFRAME_SET.has(row.tf)||[row.open,row.high,row.low,row.close].some(v=>v===null))continue;rows.push(row);}rows.sort((a,b)=>a.timeMs-b.timeMs);const byTf={};for(const row of rows)(byTf[row.tf]??=[]).push(row);return{meta,rows,byTf};}
function historyCoverage(history,nowMs){const h1=history.byTf.H1||[];if(!h1.length)return{days:0,complete:false,start:null,end:null,h1Rows:0};const start=h1[0].timeMs,end=h1.at(-1).timeMs,days=(end-start)/86400000,freshness=(nowMs-end)/86400000;return{days,complete:days>=MIN_HISTORY_DAYS-1&&freshness<=2,start:new Date(start).toISOString(),end:new Date(end).toISOString(),h1Rows:h1.length};}
function binaryBefore(rows,target){let lo=0,hi=rows.length-1,best=-1;while(lo<=hi){const mid=(lo+hi)>>1;if(rows[mid].timeMs<=target){best=mid;lo=mid+1;}else hi=mid-1;}return best>=0?rows[best]:null;}
function binaryAfter(rows,target){let lo=0,hi=rows.length-1,best=-1;while(lo<=hi){const mid=(lo+hi)>>1;if(rows[mid].timeMs>=target){best=mid;hi=mid-1;}else lo=mid+1;}return best>=0?rows[best]:null;}
function atrBefore(rows,target,period=14){let end=-1;for(let i=rows.length-1;i>=0;i--){if(rows[i].timeMs<target){end=i;break;}}if(end<period)return null;let sum=0,count=0;for(let i=end-period+1;i<=end;i++){const prev=rows[i-1]?.close??rows[i].open;sum+=Math.max(rows[i].high-rows[i].low,Math.abs(rows[i].high-prev),Math.abs(rows[i].low-prev));count++;}return count?sum/count:null;}
