function extractPivots(evidenceRows,offsetSeconds=0){const out=[];for(const row of evidenceRows){const c=compat(row);for(const [stateName,state] of Object.entries(c.states)){const list=Array.isArray(state?.confirmed_pivots)?state.confirmed_pivots:Array.isArray(state?.pivots)?state.pivots:[];for(const pivot of list){if(pivot?.confirmed===false)continue;const d=parseBrokerTimeToUtc(pivot?.time,offsetSeconds);if(!d)continue;out.push({timeMs:d.getTime(),timeIso:d.toISOString(),serverTime:String(pivot?.time||''),price:asNumber(pivot?.price),type:pivot?.type,shift:pivot?.shift,chartTimeframe:c.chartTimeframe,state:stateName,stateTf:state?.tf||'',confirmed:true});}}}const seen=new Set();return out.sort((a,b)=>a.timeMs-b.timeMs).filter(p=>{const key=`${Math.round(p.timeMs/60000)}|${p.price}|${p.stateTf}|${p.type}`;if(seen.has(key))return false;seen.add(key);return true;});}
